style.css:
@-moz-document domain("roblox.com") {
:root{
    --wallpaper: url("https://YOUR_IMAGE_URL_HERE.jpg");
}

/* Main background */
html,
body,
#rbx-body {
    background: var(--wallpaper) center center / cover fixed no-repeat !important;
}

/* Make Roblox backgrounds transparent */
.content,
.content-container,
.container-main,
#container-main,
#HomeContainer,
.game-home-page,
.game-main-content,
.profile-container,
.profile-header-top,
.section,
.card,
.game-card,
.friend-card,
.avatar-card,
.catalog-item-container,
.item-card-container,
.group-container,
.group-details,
.modal-content,
.chat-container {
    background: rgba(20,20,30,.45) !important;
    backdrop-filter: blur(14px) !important;
    -webkit-backdrop-filter: blur(14px) !important;
    border-radius: 14px !important;
}

/* Navigation */
.left-col,
.navbar,
.rbx-navbar,
.nav,
.header,
.header-content {
    background: rgba(15,15,25,.60) !important;
    backdrop-filter: blur(18px) !important;
}

/* Search bar */
input,
textarea {
    background: rgba(255,255,255,.08) !important;
    color: white !important;
    border: 1px solid rgba(255,255,255,.15) !important;
}

/* Buttons */
.btn-primary,
.btn-secondary,
.btn-control-md {
    background: rgba(255,255,255,.12) !important;
    border: 1px solid rgba(255,255,255,.15) !important;
    backdrop-filter: blur(10px);
}

/* Hover */
.game-card:hover,
.item-card-container:hover,
.card:hover {
    transform: translateY(-2px);
    transition: .2s ease;
}

/* Remove solid dark backgrounds */
[class*="dark"],
[class*="container"],
[class*="section"] {
    background-color: transparent !important;
}
}
